package com.revscope.core.intelligence.dtc

import com.revscope.core.common.i18n.StringResolver
import com.revscope.core.intelligence.R

/**
 * Plain-language explanation of a DTC code, optionally generated by Claude AI.
 *
 * @property code        DTC code string (e.g. "P0300")
 * @property explanation Human-readable description
 * @property source      Origin: an AiProvider.providerId ("anthropic" | "openai" | "gemini" |
 *                        "custom") on success, or "cache" | "fallback" | "no_key" | "offline"
 */
data class DtcExplanation(
    val code: String,
    val explanation: String,
    val source: String,
) {
    companion object {
        fun noApiKey(code: String, resolver: StringResolver) = DtcExplanation(
            code = code,
            explanation = resolver.get(R.string.ai_dtc_no_provider),
            source = "no_key",
        )

        fun offline(code: String, resolver: StringResolver) = DtcExplanation(
            code = code,
            explanation = resolver.get(R.string.ai_dtc_offline, code),
            source = "offline",
        )

        fun fallback(code: String, resolver: StringResolver) = DtcExplanation(
            code = code,
            explanation = resolver.get(R.string.ai_dtc_fallback, code),
            source = "fallback",
        )
    }
}
